import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script path does not exist")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    total_cpu = 0.0
    total_mem = 0
    start = time.time()
    while time.time() - start < timeout:
        try:
            if not p.is_running():
                break
            if p.status() == psutil.STATUS_ZOMBIE:
                break
            total_cpu += p.cpu_percent(interval=0.0)
            total_mem += p.memory_info().rss
            time.sleep(0.1)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': total_cpu, 'Memory Usage': total_mem}
